function validate([grid]) {
  if (grid.length < 1 || grid.length > 300) return 'grid needs 1 to 300 rows.';
  const cols = grid[0].length;
  if (cols < 1 || cols > 300) return 'grid needs 1 to 300 columns.';
  for (const row of grid) {
    if (row.length !== cols) return 'Every row must have the same length.';
    if (row.some(v => v !== 0 && v !== 1)) return 'Every cell is 0 or 1.';
  }
  return null;
}

