function minimumOperations(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const total = rows * cols;
  const match = new Array(total).fill(-1);
  const from = new Array(total).fill(-1);
  const seen = new Array(total).fill(-1);
  const moves = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let matching = 0;

  for (let start = 0; start < total; start++) {
    const startRow = Math.floor(start / cols);
    const startCol = start % cols;
    if (grid[startRow][startCol] === 0 || (startRow + startCol) % 2 === 1) continue;
    const queue = [start];
    let free = -1;
    for (let head = 0; head < queue.length && free === -1; head++) {
      const cell = queue[head];
      const row = Math.floor(cell / cols);
      const col = cell % cols;
      for (const [dr, dc] of moves) {
        const r = row + dr;
        const c = col + dc;
        if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] === 0) continue;
        const next = r * cols + c;
        if (seen[next] === start) continue;
        seen[next] = start;
        from[next] = cell;
        if (match[next] === -1) {
          free = next;
          break;
        }
        queue.push(match[next]);
      }
    }
    if (free === -1) continue;
    matching++;
    let white = free;
    while (white !== -1) {
      const black = from[white];
      const previous = match[black];
      match[white] = black;
      match[black] = white;
      white = previous;
    }
  }
  return matching;
}

