function minimumOperations(grid) {
  // Row-by-row DP over which ones are kept: kept ones may not touch in a row or between rows.
  let g = grid;
  if (g[0].length > g.length) g = g[0].map((_, c) => g.map(row => row[c]));
  let ones = 0;
  for (const row of g) for (const v of row) ones += v;
  const bitCount = mask => { let bits = 0; for (let m = mask; m; m &= m - 1) bits++; return bits; };
  let best = new Map([[0, 0]]);
  for (const row of g) {
    const avail = row.reduce((mask, v, c) => mask | (v << c), 0);
    const next = new Map();
    for (let mask = avail; ; mask = (mask - 1) & avail) {
      if ((mask & (mask << 1)) === 0) {
        for (const [prev, kept] of best) {
          if ((prev & mask) !== 0) continue;
          const value = kept + bitCount(mask);
          if (!next.has(mask) || next.get(mask) < value) next.set(mask, value);
        }
      }
      if (mask === 0) break;
    }
    best = next;
  }
  return ones - Math.max(...best.values());
}

