function generate(rand, size) {
  const rows = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const cols = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  const density = [0.2, 0.5, 0.6, 0.75, 0.9, 1][Math.floor(rand() * 6)];
  const grid = [];
  for (let r = 0; r < rows; r++) {
    const row = [];
    for (let c = 0; c < cols; c++) row.push(rand() < density ? 1 : 0);
    grid.push(row);
  }
  return [grid];
}
